import random
from itertools import combinations

def shortest_cycle_through_edge(adj, u, v, n):
    # BFS from u avoiding edge (u,v), find distance to v
    from collections import deque
    dist = [-1]*n
    dist[u] = 0
    q = deque([u])
    while q:
        x = q.popleft()
        for y in adj[x]:
            if (x==u and y==v) or (x==v and y==u):
                continue
            if dist[y]==-1:
                dist[y] = dist[x]+1
                q.append(y)
    if dist[v]==-1:
        return float('inf')
    return dist[v]+1

def girth(adj, n):
    g = float('inf')
    for u in range(n):
        # BFS
        from collections import deque
        dist = [-1]*n
        parent = [-1]*n
        dist[u]=0
        q=deque([u])
        while q:
            x=q.popleft()
            for y in adj[x]:
                if dist[y]==-1:
                    dist[y]=dist[x]+1
                    parent[y]=x
                    q.append(y)
                elif parent[x]!=y:
                    c = dist[x]+dist[y]+1
                    if c<g:
                        g=c
    return g

def is_3_colorable(edges, n):
    # Use simple backtracking / or check bipartite first
    # With small n, try backtracking with pruning
    adj=[set() for _ in range(n)]
    for u,v in edges:
        adj[u].add(v); adj[v].add(u)
    color=[-1]*n
    order = sorted(range(n), key=lambda x:-len(adj[x]))
    def bt(i):
        if i==n: return True
        v=order[i]
        used=set(color[u] for u in adj[v] if color[u]!=-1)
        for c in range(3):
            if c not in used:
                color[v]=c
                if bt(i+1): return True
                color[v]=-1
        return False
    return bt(0)

