import random
from itertools import combinations
from collections import deque

def add_edge_preserves_girth(adj, u, v, min_girth=7):
    # check no path length <= min_girth-2 between u and v (so cycle would be length <= min_girth-1)
    max_d = min_girth - 2  # 5
    dist = {u:0}
    q = deque([u])
    while q:
        x = q.popleft()
        if dist[x] >= max_d: continue
        for y in adj[x]:
            if y not in dist:
                dist[y] = dist[x]+1
                q.append(y)
    return v not in dist or dist[v] > max_d

def girth_of(adj, n):
    g = float('inf')
    for u in range(n):
        dist=[-1]*n; parent=[-1]*n
        dist[u]=0; q=deque([u])
        while q:
            x=q.popleft()
            for y in adj[x]:
                if dist[y]==-1:
                    dist[y]=dist[x]+1; parent[y]=x; q.append(y)
                elif parent[x]!=y:
                    c=dist[x]+dist[y]+1
                    if c<g: g=c
    return g

